    public int longestConsecutive(int... nums) {


        int longestConsecutive = 0;

        Set<Integer> set = new HashSet<>(List.of(Arrays.stream(nums).boxed().toArray(Integer[]::new)));


        for (int num : nums) {
            int count = 0;

            if (set.contains(num) && !set.contains(num - 1)) {
                count++;

                int j = num + 1;

                while (j <= Math.pow(10, 9) && j >= (-1) * Math.pow(10, 9)) {
                    if (set.contains(j)) {
                        count++;
                        j++;
                    } else {
                        break;
                    }
                }
            }

            longestConsecutive = Math.max(count, longestConsecutive);
        }
        return longestConsecutive;

    }
